#!/usr/bin/env node
/**
 * Builds the dev relay by bundling scripts/dev-relay.ts with extension source.
 * Aliases the `vscode` module to a minimal shim so extension code runs outside VS Code.
 */
'use strict'

const esbuild = require('esbuild')
const path = require('path')

esbuild.buildSync({
  entryPoints: [path.join(__dirname, 'dev-relay.ts')],
  bundle: true,
  platform: 'node',
  target: 'node18',
  outfile: path.join(__dirname, '.dev-relay.js'),
  alias: {
    'vscode': path.join(__dirname, 'vscode-shim.js'),
  },
  sourcemap: true,
  logLevel: 'warning',
})

#!/usr/bin/env node
/**
 * Dev relay server — wraps the shared relay with a standalone HTTP server
 * that includes CORS headers for cross-origin dev mode (Next.js on :3000).
 */
import * as http from 'http'
import { createRelay } from './relay'
import { DEFAULT_RELAY_PORT, DEV_WEB_ORIGIN_PATTERN } from '../extension/src/constants'
import { isLoopbackHost } from '../extension/src/request-guard'

async function main() {
  const workspace = process.argv[2] || process.cwd()

  console.log('Starting Agent Flow dev relay...\n')
  console.log(`Workspace: ${workspace}`)

  const relay = await createRelay({ workspace, verbose: true })

  const server = http.createServer((req, res) => {
    // Reject DNS-rebinding requests, which reach 127.0.0.1 under a foreign Host.
    if (!isLoopbackHost(req.headers.host)) {
      res.writeHead(403, { 'Content-Type': 'text/plain' })
      res.end('Forbidden')
      return
    }

    // Echo back the request Origin if it matches a localhost pattern, so
    // CORS survives Next.js picking a fallback port when 3000 is busy.
    const origin = req.headers.origin
    if (typeof origin === 'string' && DEV_WEB_ORIGIN_PATTERN.test(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin)
      res.setHeader('Vary', 'Origin')
    }
    res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS')
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type')

    if (req.method === 'OPTIONS') {
      res.writeHead(204)
      res.end()
      return
    }

    if (req.url === '/events') {
      return relay.handleSSE(req, res)
    }

    res.writeHead(200, { 'Content-Type': 'text/plain' })
    res.end('Agent Flow Dev Relay')
  })

  server.listen(DEFAULT_RELAY_PORT, '127.0.0.1', () => {
    console.log(`\nSSE relay on http://127.0.0.1:${DEFAULT_RELAY_PORT}/events`)
    console.log('Ready! Events will appear in the web app.')
  })

  function cleanup() {
    server.close()
    relay.dispose()
    process.exit(0)
  }
  process.on('SIGINT', cleanup)
  process.on('SIGTERM', cleanup)
}

main().catch(e => {
  console.error('Failed to start dev relay:', e)
  process.exit(1)
})

/**
 * Minimal vscode module shim for running extension code outside VS Code.
 * Only implements what hook-server.ts and session-watcher.ts actually use.
 */
'use strict'

class EventEmitter {
  constructor() { this._listeners = [] }
  get event() {
    return (listener) => {
      this._listeners.push(listener)
      return { dispose: () => { const i = this._listeners.indexOf(listener); if (i >= 0) this._listeners.splice(i, 1) } }
    }
  }
  fire(data) { for (const l of this._listeners) l(data) }
  dispose() { this._listeners = [] }
}

module.exports = {
  EventEmitter,
  workspace: {
    workspaceFolders: [{ uri: { fsPath: process.cwd() } }],
    getConfiguration: () => ({ get: () => undefined }),
  },
  window: {
    showInformationMessage: () => {},
  },
}

import { createRoot } from 'react-dom/client'
import { AgentVisualizer } from './components/agent-visualizer'
import './app/globals.css'

// Standalone CLI entry — no VS Code API, connects to relay via SSE
const rootElement = document.getElementById('root')
if (!rootElement) throw new Error('Root element #root not found')
const root = createRoot(rootElement)
root.render(<AgentVisualizer />)

import {
  type Agent,
  type TimelineEntry,
  emptyContextBreakdown,
} from '@/lib/agent-types'
import { COLORS } from '@/lib/colors'
import { AGENT_SPAWN_DISTANCE } from '@/lib/canvas-constants'
import { withTimelineModel } from '@/lib/timeline-models'
import { pushTimelineBlock, type ProcessEventContext, type MutableEventState } from './process-event'
import { edgeId, asString, asBoolean } from './types'

export function handleAgentSpawn(
  payload: Record<string, unknown>,
  currentTime: number,
  state: MutableEventState,
  ctx: ProcessEventContext,
): void {
  const name = asString(payload.name)
  const parentId = typeof payload.parent === 'string' ? payload.parent : undefined
  const isMain = asBoolean(payload.isMain)
  const task = typeof payload.task === 'string' ? payload.task : undefined
  const model = typeof payload.model === 'string' ? payload.model : undefined
  const runtime = payload.runtime === 'codex' ? 'codex' as const : undefined

  // If the agent already exists (e.g. session resuming after inactivity),
  // reactivate it instead of replacing — preserves accumulated stats.
  const existing = state.agents.get(name)
  if (existing) {
    state.agents.set(name, {
      ...existing,
      state: 'idle',
      ...(task ? { task } : {}),
      ...(model ? { model, tokensMax: ctx.getContextWindowSize(model) } : {}),
      ...(runtime ? { runtime } : {}),
    })
    if (model) recordTimelineModel(state, name, model)
    return
  }

  let x = 0, y = 0
  if (parentId) {
    const parent = state.agents.get(parentId)
    if (parent) {
      // Collect angles of existing siblings so we can avoid spawning too close
      const siblingAngles: number[] = []
      for (const a of state.agents.values()) {
        if (a.parentId === parentId && a.id !== name) {
          siblingAngles.push(Math.atan2(a.y - parent.y, a.x - parent.x))
        }
      }

      let angle: number
      if (siblingAngles.length === 0) {
        // First child: use hash-based angle
        const hash = name.split('').reduce((h, c) => ((h << 5) - h) + c.charCodeAt(0), 0)
        angle = (Math.abs(hash) % 360) * (Math.PI / 180)
      } else {
        // Find the largest angular gap between existing siblings and place in the middle
        siblingAngles.sort((a, b) => a - b)
        let bestGap = 0
        let bestMid = 0
        for (let i = 0; i < siblingAngles.length; i++) {
          const next = i + 1 < siblingAngles.length ? siblingAngles[i + 1] : siblingAngles[0] + Math.PI * 2
          const gap = next - siblingAngles[i]
          if (gap > bestGap) {
            bestGap = gap
            bestMid = siblingAngles[i] + gap / 2
          }
        }
        angle = bestMid
      }

      x = parent.x + Math.cos(angle) * AGENT_SPAWN_DISTANCE
      y = parent.y + Math.sin(angle) * AGENT_SPAWN_DISTANCE
    }
  }

  const agent: Agent = {
    id: name, name, state: 'idle',
    parentId: parentId || null,
    tokensUsed: 0, tokensMax: ctx.getContextWindowSize(model),
    contextBreakdown: emptyContextBreakdown(),
    toolCalls: 0, timeAlive: 0,
    x, y, vx: 0, vy: 0,
    pinned: false, isMain,
    ...(runtime ? { runtime } : {}),
    ...(model ? { model } : {}),
    task,
    spawnTime: currentTime,
    opacity: 0, scale: 0.3,
    messageBubbles: [],
  }
  state.agents.set(name, agent)

  if (parentId) {
    state.edges.push({ id: edgeId(parentId, name), from: parentId, to: name, type: 'parent-child', opacity: 0 })
  }

  // Keep models recorded by an earlier entry for this name (the agent itself
  // may have been cleaned up after fading out)
  const previousModels = state.timelineEntries.get(name)?.models
  const timelineEntry: TimelineEntry = {
    id: `timeline-${name}`,
    agentId: name,
    agentName: name,
    startTime: currentTime,
    blocks: [],
    ...(previousModels ? { models: previousModels } : {}),
  }
  pushTimelineBlock(timelineEntry, currentTime, { type: 'idle', label: 'Starting', color: COLORS.idle }, ctx)
  state.timelineEntries.set(name, timelineEntry)
  if (model) recordTimelineModel(state, name, model)

  state.conversations.set(name, [])

  if (!ctx.skipForceSync) {
    setTimeout(() => ctx.syncForceSimulation(state.agents, state.edges), 0)
  }
}

export function handleAgentComplete(
  payload: Record<string, unknown>,
  currentTime: number,
  state: MutableEventState,
  ctx: ProcessEventContext,
): void {
  const name = asString(payload.name)
  const agent = state.agents.get(name)
  if (agent && agent.state !== 'complete') {
    state.agents.set(name, { ...agent, state: 'complete', completeTime: currentTime })

    const entry = state.timelineEntries.get(name)
    if (entry) {
      pushTimelineBlock(entry, currentTime, { type: 'complete', label: 'Done', color: COLORS.complete, endTime: currentTime }, ctx)
      entry.endTime = currentTime
    }

    const agentsToComplete = [name]
    for (const [childId, childAgent] of state.agents) {
      if (childAgent.parentId === name && childAgent.state !== 'complete') {
        state.agents.set(childId, { ...childAgent, state: 'complete', completeTime: currentTime })
        agentsToComplete.push(childId)
        const childEntry = state.timelineEntries.get(childId)
        if (childEntry) {
          pushTimelineBlock(childEntry, currentTime, { type: 'complete', label: 'Done', color: COLORS.complete, endTime: currentTime }, ctx)
          childEntry.endTime = currentTime
        }
      }
    }

    for (const [tcId, tc] of state.toolCalls) {
      if (agentsToComplete.includes(tc.agentId) && tc.state === 'running') {
        state.toolCalls.set(tcId, { ...tc, state: 'complete', completeTime: currentTime })
      }
    }
  }
}

export function handlePermissionRequested(
  payload: Record<string, unknown>,
  currentTime: number,
  state: MutableEventState,
  ctx: ProcessEventContext,
): void {
  const agentName = asString(payload.agent, 'Orchestrator')
  const agent = state.agents.get(agentName)
  if (agent && agent.state !== 'complete') {
    state.agents.set(agentName, {
      ...agent,
      state: 'waiting_permission',
    })

    const entry = state.timelineEntries.get(agentName)
    if (entry) {
      pushTimelineBlock(entry, currentTime, { type: 'idle', label: 'Permission', color: COLORS.waiting_permission }, ctx)
    }
  }
}

export function handleAgentIdle(
  payload: Record<string, unknown>,
  state: MutableEventState,
): void {
  const idleName = asString(payload.name)
  const idleAgent = state.agents.get(idleName)
  if (idleAgent && (idleAgent.state === 'tool_calling' || idleAgent.state === 'waiting_permission')) {
    state.agents.set(idleName, { ...idleAgent, state: 'thinking', currentTool: undefined })
  }
}

export function handleModelDetected(
  payload: Record<string, unknown>,
  state: MutableEventState,
  ctx: ProcessEventContext,
): void {
  const agentName = asString(payload.agent)
  const model = asString(payload.model)
  const agent = state.agents.get(agentName)
  if (agent) {
    state.agents.set(agentName, {
      ...agent,
      model,
      tokensMax: ctx.getContextWindowSize(model),
    })
  }
  recordTimelineModel(state, agentName, model)
}

/** Add a model to the agent's timeline entry, which outlives the agent node. */
function recordTimelineModel(state: MutableEventState, agentName: string, model: string): void {
  const entry = state.timelineEntries.get(agentName)
  if (!entry) return
  const updated = withTimelineModel(entry, model)
  if (updated !== entry) state.timelineEntries.set(agentName, updated)
}

import { COLORS } from '@/lib/colors'
import type { MutableEventState } from './process-event'
import { edgeId, asString, LABEL_LEN_SHORT } from './types'

export function handleSubagentDispatch(
  payload: Record<string, unknown>,
  currentTime: number,
  state: MutableEventState,
): void {
  const parentName = asString(payload.parent)
  const childName = asString(payload.child)
  const eid = edgeId(parentName, childName)
  const task = asString(payload.task)

  state.particles.push({
    id: `p-disp-${currentTime}-${eid}`,
    edgeId: eid, progress: 0,
    type: 'dispatch', color: COLORS.dispatch,
    size: 6, trailLength: 0.2,
    label: task.slice(0, LABEL_LEN_SHORT),
  })
}

export function handleSubagentReturn(
  payload: Record<string, unknown>,
  currentTime: number,
  state: MutableEventState,
): void {
  const parentName = asString(payload.parent)
  const childName = asString(payload.child)
  const eid = edgeId(parentName, childName)
  const summary = asString(payload.summary)

  state.particles.push({
    id: `p-ret-${currentTime}-${eid}`,
    edgeId: eid, progress: 1,
    type: 'return', color: COLORS.return,
    size: 5, trailLength: 0.2,
    label: summary.slice(0, LABEL_LEN_SHORT),
  })
}

import { COLORS } from '@/lib/colors'
import { TOOL_DEDUP_WINDOW_S } from '@/lib/canvas-constants'
import { pushTimelineBlock, type ProcessEventContext, type MutableEventState } from './process-event'
import { appendConversation, asString, asBoolean, LABEL_LEN_PARTICLE, LABEL_LEN_TIMELINE } from './types'

/** Extract file path from tool input data or fall back to first token of args */
function extractFilePath(inputData?: Record<string, unknown>, args?: string): string {
  return asString(inputData?.file_path) || args?.split(' ')[0] || ''
}

export function handleToolCallStart(
  payload: Record<string, unknown>,
  currentTime: number,
  state: MutableEventState,
  ctx: ProcessEventContext,
): void {
  const agentName = asString(payload.agent)
  const toolName = asString(payload.tool)
  const args = asString(payload.args)
  const inputData = (payload.inputData && typeof payload.inputData === 'object' && !Array.isArray(payload.inputData))
    ? payload.inputData as Record<string, unknown> : undefined
  const agent = state.agents.get(agentName)

  if (agent) {
    // Dedup: skip if there's already a running tool call for the same agent+tool
    // created within the last 3 seconds (race between Hook Server and Session Watcher)
    let isDuplicate = false
    for (const tc of state.toolCalls.values()) {
      if (tc.agentId === agentName && tc.toolName === toolName && tc.state === 'running' && (currentTime - tc.startTime) < TOOL_DEDUP_WINDOW_S) {
        isDuplicate = true
        break
      }
    }
    if (isDuplicate) return

    state.agents.set(agentName, {
      ...agent,
      state: 'tool_calling',
      currentTool: toolName,
      toolCalls: agent.toolCalls + 1
    })

    const toolId = `tool-${agentName}-${toolName}-${currentTime}`

    const pos = ctx.findToolSlot(agent, state.agents, state.toolCalls, currentTime)

    state.toolCalls.set(toolId, {
      id: toolId, agentId: agentName, toolName,
      state: 'running',
      args,
      inputData,
      x: pos.x,
      y: pos.y,
      startTime: currentTime,
      opacity: 0,
    })

    state.edges.push({ id: `edge-${toolId}`, from: agentName, to: toolId, type: 'tool', opacity: 0 })

    state.particles.push({
      id: `p-tc-${currentTime}-${toolId}`,
      edgeId: `edge-${toolId}`, progress: 0,
      type: 'tool_call', color: COLORS.tool,
      size: 4, trailLength: 0.15,
      label: `${toolName} ${args}`.slice(0, LABEL_LEN_PARTICLE),
    })

    // Timeline block
    const entry = state.timelineEntries.get(agentName)
    if (entry) {
      pushTimelineBlock(entry, currentTime, { type: 'tool_call', label: `${toolName}: ${args}`.slice(0, LABEL_LEN_TIMELINE), color: COLORS.tool }, ctx)
    }

    // Track file attention
    if (toolName === 'Read' || toolName === 'Edit' || toolName === 'Write') {
      const filePath = extractFilePath(inputData, args)
      if (filePath) {
        const prev = state.fileAttention.get(filePath)
        const updated = prev
          ? { ...prev, agents: [...prev.agents] }
          : { path: filePath, reads: 0, edits: 0, totalTokens: 0, lastAccessed: currentTime, agents: [] as string[] }
        if (toolName === 'Read') updated.reads++
        else updated.edits++
        updated.lastAccessed = currentTime
        if (!updated.agents.includes(agentName)) updated.agents.push(agentName)
        state.fileAttention.set(filePath, updated)
      }
    }

    appendConversation(state.conversations, agentName, {
      type: 'tool_call', content: `> ${toolName} ${args}`, timestamp: currentTime,
      toolName, inputData,
    })
  }
}

export function handleToolCallEnd(
  payload: Record<string, unknown>,
  currentTime: number,
  state: MutableEventState,
  ctx: ProcessEventContext,
): void {
  const agentName = asString(payload.agent)
  const toolName = asString(payload.tool)
  const result = asString(payload.result, 'Done')
  const tokenCost = typeof payload.tokenCost === 'number' ? payload.tokenCost : undefined
  const isError = asBoolean(payload.isError)
  const errorMessage = typeof payload.errorMessage === 'string' ? payload.errorMessage : undefined
  const agent = state.agents.get(agentName)

  if (agent) {
    state.agents.set(agentName, {
      ...agent,
      state: isError ? 'error' : 'thinking',
      currentTool: undefined,
      tokensUsed: agent.tokensUsed + (tokenCost ?? 0),
    })

    const toolState: 'error' | 'complete' = isError ? 'error' : 'complete'
    for (const [id, tc] of state.toolCalls) {
      if (tc.agentId === agentName && tc.toolName === toolName && tc.state === 'running') {
        state.toolCalls.set(id, { ...tc, state: toolState, completeTime: currentTime, result, tokenCost, errorMessage: isError ? (errorMessage || result) : undefined })

        const edgeId = `edge-${id}`
        // Snap any still-traveling outgoing particle to the end
        const outIdx = state.particles.findIndex(p => p.edgeId === edgeId && p.type === 'tool_call')
        if (outIdx !== -1) state.particles[outIdx] = { ...state.particles[outIdx], progress: 0.95 }

        state.particles.push({
          id: `p-tr-${currentTime}-${id}`,
          edgeId, progress: 1,
          type: 'tool_return', color: COLORS.return,
          size: 4, trailLength: 0.15,
          label: result.slice(0, LABEL_LEN_PARTICLE),
        })
        break
      }
    }

    // Timeline block end
    const entry = state.timelineEntries.get(agentName)
    if (entry) {
      if (isError) {
        const lastBlock = entry.blocks[entry.blocks.length - 1]
        if (lastBlock && !lastBlock.endTime) {
          lastBlock.color = COLORS.error
          lastBlock.label = `${toolName}: FAILED`
        }
      }
      pushTimelineBlock(entry, currentTime, { type: 'thinking', label: 'Thinking...', color: COLORS.thinking }, ctx)
    }

    // File attention token cost
    if (tokenCost) {
      const matchedTc = Array.from(state.toolCalls.values()).find(tc => tc.agentId === agentName && tc.toolName === toolName)
      const filePath = extractFilePath(matchedTc?.inputData, matchedTc?.args)
      if (filePath) {
        const existing = state.fileAttention.get(filePath)
        if (existing) {
          state.fileAttention.set(filePath, { ...existing, totalTokens: existing.totalTokens + tokenCost })
        }
      }
    }

    appendConversation(state.conversations, agentName, {
      type: 'tool_result',
      content: `< ${result}${tokenCost ? ` (${tokenCost} tokens)` : ''}`,
      timestamp: currentTime,
      toolName,
    })
  }
}

import {
  Agent,
  ToolCallNode,
  Edge,
  SimulationEvent,
  type TimelineEntry,
  type TimelineBlock,
} from '@/lib/agent-types'
import type { SimulationState, ConversationMessage } from './types'
import { handleAgentSpawn, handleAgentComplete, handleAgentIdle, handlePermissionRequested, handleModelDetected } from './handle-agent-events'
import { handleToolCallStart, handleToolCallEnd } from './handle-tool-events'
import { handleMessage, handleContextUpdate } from './handle-message-events'
import { handleSubagentDispatch, handleSubagentReturn } from './handle-subagent-events'

export interface ProcessEventContext {
  syncForceSimulation: (agents: Map<string, Agent>, edges: Edge[]) => void
  findToolSlot: (agent: Agent, agents: Map<string, Agent>, toolCalls: Map<string, ToolCallNode>, currentTime: number) => { x: number; y: number }
  getContextWindowSize: (modelId?: string) => number
  blockIdCounter: { current: number }
  skipForceSync: boolean
}

/** Mutable collections that handlers mutate in place during a single processEvent call. */
export interface MutableEventState {
  agents: Map<string, Agent>
  toolCalls: Map<string, ToolCallNode>
  particles: SimulationState['particles']
  edges: Edge[]
  discoveries: SimulationState['discoveries']
  fileAttention: SimulationState['fileAttention']
  timelineEntries: SimulationState['timelineEntries']
  conversations: Map<string, ConversationMessage[]>
}

/** Close the last open block on a timeline entry and push a new one. */
export function pushTimelineBlock(
  entry: TimelineEntry,
  currentTime: number,
  block: Pick<TimelineBlock, 'type' | 'label' | 'color'> & { endTime?: number },
  ctx: ProcessEventContext,
): void {
  const lastBlock = entry.blocks[entry.blocks.length - 1]
  if (lastBlock && !lastBlock.endTime) lastBlock.endTime = currentTime
  entry.blocks.push({
    id: `block-${ctx.blockIdCounter.current++}`,
    type: block.type,
    startTime: currentTime,
    endTime: block.endTime,
    label: block.label,
    color: block.color,
  })
}

/** Shallow-compare two Maps by reference equality of values */
function mapsEqual<K, V>(a: Map<K, V>, b: Map<K, V>): boolean {
  if (a.size !== b.size) return false
  for (const [k, v] of a) if (b.get(k) !== v) return false
  return true
}

export function processEvent(event: SimulationEvent, prev: SimulationState, ctx: ProcessEventContext): SimulationState {
      const state: MutableEventState = {
        agents: new Map(prev.agents),
        toolCalls: new Map(prev.toolCalls),
        particles: [...prev.particles],
        edges: [...prev.edges],
        discoveries: [...prev.discoveries],
        fileAttention: new Map(prev.fileAttention),
        timelineEntries: new Map(prev.timelineEntries),
        conversations: new Map(prev.conversations),
      }

      switch (event.type) {
        case 'agent_spawn':       handleAgentSpawn(event.payload, prev.currentTime, state, ctx); break
        case 'agent_complete':    handleAgentComplete(event.payload, prev.currentTime, state, ctx); break
        case 'agent_idle':        handleAgentIdle(event.payload, state); break
        case 'model_detected':    handleModelDetected(event.payload, state, ctx); break
        case 'tool_call_start':   handleToolCallStart(event.payload, prev.currentTime, state, ctx); break
        case 'tool_call_end':     handleToolCallEnd(event.payload, prev.currentTime, state, ctx); break
        case 'message':           handleMessage(event.payload, prev.currentTime, state); break
        case 'context_update':    handleContextUpdate(event.payload, state); break
        case 'subagent_dispatch': handleSubagentDispatch(event.payload, prev.currentTime, state); break
        case 'subagent_return':   handleSubagentReturn(event.payload, prev.currentTime, state); break
        case 'permission_requested': handlePermissionRequested(event.payload, prev.currentTime, state, ctx); break
      }

      // Stabilize references for unchanged collections to prevent
      // downstream React useMemo/re-render cascades (O(n log n) sorts etc.)
      return {
        ...prev,
        agents: state.agents, toolCalls: state.toolCalls,
        particles: state.particles, edges: state.edges,
        discoveries: state.discoveries,
        fileAttention: mapsEqual(prev.fileAttention, state.fileAttention) ? prev.fileAttention : state.fileAttention,
        timelineEntries: mapsEqual(prev.timelineEntries, state.timelineEntries) ? prev.timelineEntries : state.timelineEntries,
        conversations: mapsEqual(prev.conversations, state.conversations) ? prev.conversations : state.conversations,
      }
}

import type {
  Agent,
  ToolCallNode,
  Particle,
  Edge,
  Discovery,
  FileAttention,
  TimelineEntry,
  SimulationEvent,
} from '@/lib/agent-types'
import type { SimulationNodeDatum, SimulationLinkDatum } from 'd3-force'

export interface SimulationState {
  agents: Map<string, Agent>
  toolCalls: Map<string, ToolCallNode>
  particles: Particle[]
  edges: Edge[]
  discoveries: Discovery[]
  fileAttention: Map<string, FileAttention>
  timelineEntries: Map<string, TimelineEntry>
  conversations: Map<string, ConversationMessage[]>
  currentTime: number
  isPlaying: boolean
  speed: number
  eventIndex: number
  eventLog: SimulationEvent[]
  /** Highest currentTime ever reached (for scrubber range in live mode) */
  maxTimeReached: number
}

/** Create an empty simulation state, optionally preserving specific fields */
export function createEmptyState(overrides?: Partial<SimulationState>): SimulationState {
  return {
    agents: new Map(),
    toolCalls: new Map(),
    particles: [],
    edges: [],
    discoveries: [],
    fileAttention: new Map(),
    timelineEntries: new Map(),
    conversations: new Map(),
    currentTime: 0,
    isPlaying: false,
    speed: 1,
    eventIndex: 0,
    eventLog: [],
    maxTimeReached: 0,
    ...overrides,
  }
}

let _msgIdCounter = 0
export function nextMsgId(): string { return `msg-${_msgIdCounter++}` }

export interface ConversationMessage {
  id: string
  type: 'tool_call' | 'tool_result' | 'assistant' | 'user' | 'thinking'
  content: string
  timestamp: number
  toolName?: string
  inputData?: Record<string, unknown>
}

/** Max canvas message bubbles kept per agent (oldest are dropped) */
export const MAX_BUBBLES = 20

/** Max conversation messages kept per agent (oldest are dropped) */
export const MAX_CONVERSATION_MESSAGES = 200

/** Max events kept in the event log for seeking (oldest are dropped) */
export const MAX_EVENT_LOG = 5000

/** Append a message to a conversation, creating the array if needed.
 *  Auto-assigns a unique id if not provided.
 *  Caps history at MAX_CONVERSATION_MESSAGES per agent. */
export function appendConversation(
  conversations: Map<string, ConversationMessage[]>,
  agentName: string,
  message: Omit<ConversationMessage, 'id'> & { id?: string },
): void {
  const msg: ConversationMessage = { id: message.id ?? nextMsgId(), ...message }
  const msgs = conversations.get(agentName) || []
  const updated = [...msgs, msg]
  conversations.set(agentName, updated.length > MAX_CONVERSATION_MESSAGES ? updated.slice(-MAX_CONVERSATION_MESSAGES) : updated)
}

/** Build a deterministic edge ID from two node names */
export function edgeId(from: string, to: string): string {
  return `edge-${from}-${to}`
}

// ── Safe payload extraction helpers ──────────────────────────────────
export function asString(v: unknown, fallback = ''): string { return typeof v === 'string' ? v : fallback }
export function asNumber(v: unknown, fallback = 0): number { return typeof v === 'number' ? v : fallback }
export function asBoolean(v: unknown, fallback = false): boolean { return typeof v === 'boolean' ? v : fallback }

// ── Truncation length constants ──────────────────────────────────────
export const LABEL_LEN_SHORT = 25
export const LABEL_LEN_PARTICLE = 30
export const LABEL_LEN_TIMELINE = 40
export const LABEL_LEN_NAME = 40
export const LABEL_LEN_TASK = 120
export const LABEL_LEN_BUBBLE = 200

export interface ForceNode extends SimulationNodeDatum {
  id: string
}

export interface ForceLink extends SimulationLinkDatum<ForceNode> {
  id: string
}

export interface UseAgentSimulationOptions {
  /** If true, use MOCK_SCENARIO for demo playback. Default: true */
  useMockData?: boolean
  /** External events to process (from VS Code bridge). Consumed each frame. */
  externalEvents?: readonly SimulationEvent[]
  /** Called after external events are consumed */
  onExternalEventsConsumed?: () => void
  /** If set, only process events matching this session ID */
  sessionFilter?: string | null
  /** Ref updated synchronously when session changes (avoids stale closure in rAF) */
  sessionFilterRef?: React.RefObject<string | null>
  /** If true, CLAUDE_CODE_DISABLE_1M_CONTEXT is set — cap context window to 200k */
  disable1MContext?: boolean
}

import { test } from 'node:test'
import { strict as assert } from 'node:assert'
import { shouldCommitFrame, UI_THROTTLE_MS } from './ui-throttle'

const base = { now: 10_000, lastCommitAt: 9_000, processedEvents: false, currentTime: 12.4, lastCommittedTime: 12.1 }

test('commits when events were processed', () => {
  assert.equal(shouldCommitFrame({ ...base, processedEvents: true }), true)
})

test('commits when the clock crosses a whole second without events (#90)', () => {
  assert.equal(shouldCommitFrame({ ...base, currentTime: 13.02 }), true)
})

test('skips frames where nothing visible changed', () => {
  assert.equal(shouldCommitFrame(base), false)
})

test('throttles to UI_THROTTLE_MS', () => {
  const recent = { ...base, lastCommitAt: base.now - UI_THROTTLE_MS + 1 }
  assert.equal(shouldCommitFrame({ ...recent, processedEvents: true }), false)
  assert.equal(shouldCommitFrame({ ...recent, currentTime: 20 }), false)
})

test('commits on the first frame', () => {
  assert.equal(shouldCommitFrame({ ...base, lastCommitAt: 0, processedEvents: true }), true)
})

/** ms between React state updates — canvas uses frameRef for smooth 60fps */
export const UI_THROTTLE_MS = 250

/**
 * Whether the animation loop should push the current frame to React state.
 *
 * The canvas reads frameRef every frame, but the control bar (elapsed time,
 * scrubber knob) and counters only update on a React render. Render when
 * events were processed, or when the clock crossed a whole second so the
 * mm:ss label keeps moving through quiet stretches of the timeline. Both are
 * throttled to UI_THROTTLE_MS.
 */
export function shouldCommitFrame(opts: {
  now: number
  lastCommitAt: number
  processedEvents: boolean
  currentTime: number
  lastCommittedTime: number
}): boolean {
  if (opts.lastCommitAt && opts.now - opts.lastCommitAt < UI_THROTTLE_MS) return false
  return opts.processedEvents || Math.floor(opts.currentTime) !== Math.floor(opts.lastCommittedTime)
}

import { test } from 'node:test'
import { strict as assert } from 'node:assert'
import type { TimelineEntry } from './agent-types'
import { withTimelineModel, formatTimelineModels } from './timeline-models'

const entry: TimelineEntry = { id: 'timeline-a', agentId: 'a', agentName: 'a', startTime: 0, blocks: [] }

test('records models in first-seen order', () => {
  let e = withTimelineModel(entry, 'claude-opus-5-5')
  e = withTimelineModel(e, 'claude-fable-5-1')
  e = withTimelineModel(e, 'claude-opus-5-5')
  assert.deepEqual(e.models, ['claude-opus-5-5', 'claude-fable-5-1'])
})

test('returns the same entry when nothing changes', () => {
  const e = withTimelineModel(entry, 'claude-opus-5-5')
  assert.equal(withTimelineModel(e, 'claude-opus-5-5'), e)
  assert.equal(withTimelineModel(e, ''), e)
  assert.equal(entry.models, undefined)
})

test('formats models for display, merging variants with the same name', () => {
  assert.equal(formatTimelineModels(undefined), '')
  assert.equal(formatTimelineModels(['claude-opus-5-5', 'claude-opus-5-5[1m]', 'claude-fable-5-1']), 'Opus 5.5 → Fable 5.1')
})

